// todo-api.js
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

let todos = [];

// Validate title for create/update operations
const validateTodoTitle = (title) => {
    return typeof title === 'string' && title.length >= 1 && title.length <= 100;
};

// Get all todos with optional filter by completed status
app.get('/todos', (req, res) => {
    const { completed } = req.query;
    let filteredTodos = todos.slice();

    if (completed !== undefined) {
        try {
            filteredTodos = filteredTodos.filter(todo => todo.completed === JSON.parse(completed));
        } catch (e) {
            return res.status(400).json({ error: 'Invalid completed filter' });
        }
    }

    res.json(filteredTodos);
});

// Get single todo by ID
app.get('/todos/:id', (req, res) => {
    const todo = todos.find(t => t.id === req.params.id);
    if (!todo) return res.status(404).json({ error: 'Todo not found' });
    res.json(todo);
});

// Create new todo
app.post('/todos', (req, res) => {
    const { title } = req.body;

    if (!validateTodoTitle(title)) {
        return res.status(400).json({ error: 'Invalid title' });
    }

    const newTodo = {
        id: uuidv4(),
        title,
        completed: false,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };

    todos.push(newTodo);
    res.status(201).json(newTodo);
});

// Update existing todo
app.put('/todos/:id', (req, res) => {
    const { title } = req.body;
    const id = req.params.id;
    const todoIndex = todos.findIndex(t => t.id === id);

    if (todoIndex === -1) return res.status(404).json({ error: 'Todo not found' });

    if (!validateTodoTitle(title)) {
        return res.status(400).json({ error: 'Invalid title' });
    }

    const updatedTodo = {
        ...todos[todoIndex],
        title,
        completed: req.body.completed || todos[todoIndex].completed,
        updatedAt: new Date().toISOString()
    };

    if ('completed' in req.body) {
        updatedTodo.completed = !!req.body.completed;
    }

    todos[todoIndex] = updatedTodo;
    res.json(updatedTodo);
});

// Delete todo by ID
app.delete('/todos/:id', (req, res) => {
    const id = req.params.id;
    const todoIndex = todos.findIndex(t => t.id === id);

    if (todoIndex === -1) return res.status(404).json({ error: 'Todo not found' });

    todos.splice(todoIndex, 1);
    res.json({ message: 'Todo deleted successfully' });
});

module.exports = app;

// test.js
const request = require('supertest');
const app = require('./todo-api');

describe('Todo API', () => {
    let server;

    beforeEach(() => {
        server = app.listen(3000);
    });

    afterEach(() => {
        if (server) server.close();
    });

    describe('GET /todos', () => {
        it('should return all todos', async () => {
            const response = await request(server).get('/todos');
            expect(response.statusCode).toBe(200);
            expect(response.body).toHaveLength(todos.length);
        });
    });

    // ... other test cases would go here ...
});

